<script setup lang="ts">
// Author by Lab | zefry. Public read-only menu; no payment or ordering implied.
import { computed, ref } from 'vue';
import { Head } from '@inertiajs/vue3';
import { locale, setLocale } from '../../i18n';
import { formatMoney, setCurrencyPreferences }  from '../../business-money';
import WorkspaceIcon from '../../components/WorkspaceIcon.vue';
type MenuItem={category:string;name:string;price_atomic:string;currency:string;scale:number;spotlight:boolean};
const props=defineProps<{title:string;description:string;items:MenuItem[];preferences:unknown}>();
setCurrencyPreferences(props.preferences);
const index=ref(0);const pages=computed(()=>Math.max(1,Math.ceil(props.items.length/6)));const current=computed(()=>props.items.slice(index.value*6,index.value*6+6));
const label=(id:string,en:string)=>locale.value==='id'?id:en;
function changeLanguage(event:Event){setLocale((event.target as HTMLSelectElement).value);}
</script>
<template>
 <Head :title="title+' | oneQay'"/>
 <main class="public-menu"><header><div class="public-brand">one<span>Qay</span></div><label class="menu-language"><WorkspaceIcon name="globe" :size="18"/><select :value="locale" :aria-label="label('Bahasa','Language')" @change="changeLanguage"><option value="id">ID</option><option value="en">ENG</option></select></label></header><section class="menu-cover"><div><p class="menu-kicker">{{label('BUKU MENU','MENU BOOK')}}</p><h1>{{title}}</h1><p>{{description}}</p></div><WorkspaceIcon name="book-open" :size="44"/></section>
 <section class="menu-sheet" aria-live="polite"><div class="sheet-header"><h2>{{label('Pilihan menu','Our menu')}}</h2><span>{{label('Halaman','Page')}} {{index+1}} / {{pages}}</span></div><p v-if="!items.length">{{label('Menu sedang disiapkan.','The menu is being prepared.')}}</p><div class="menu-grid"><article v-for="(item,i) in current" :key="index+'-'+i" class="menu-item"><p>{{item.category}} <span v-if="item.spotlight"> · {{label('Pilihan','Featured')}}</span></p><div><strong>{{item.name}}</strong><b>{{formatMoney(item.price_atomic,item.currency,item.scale)}}</b></div></article></div><nav :aria-label="label('Halaman buku menu','Menu book pages')"><button :disabled="index===0" @click="index--"><WorkspaceIcon name="chevron-left" :size="18"/> {{label('Sebelumnya','Previous')}}</button><button :disabled="index>=pages-1" @click="index++">{{label('Berikutnya','Next')}} <WorkspaceIcon name="chevron-right" :size="18"/></button></nav></section><footer>© {{new Date().getFullYear()}} oneQay</footer></main>
</template>
